mapper.sql:
FROM CSPD001TM A , CSPD201TM EP -- 수출테이블 , CSPD202TM IP -- 수입테이블 WHERE A.QLAS_CRPE_ENO = #{userId} AND A.AI_INPT_QLAS_ACVT_CD IN ('120', '160') AND A.AI_INPT_ACVT_CD IN ('140', '160') AND A.ACTL_FX_REFNO = EP.FX_ACNO(+) AND A.FX_REFNO_SRNO = EP.XPO_CVRG_MK_SQ(+) AND A.ACTL_FX_REFNO = IP.FX_ACNO(+) AND A.FX_REFNO_SRNO = IP.TDOC_RCP_SRNO(+)
AND A.AI_INPT_QLAS_PROS_CD = #{inptPrcsCd}
AND A.ACTL_FX_REFNO LIKE '%' || UPPER(#{actlFxRefno}) || '%'
AND A.INPT_RCP_DT BETWEEN REPLACE(#{schSdate1}, '-', '') AND REPLACE(#{schEdate1}, '-', '')
)AA
LEFT OUTER JOIN CSPD112TI E ON E.AI_INPT_GRP_CD = '150' AND E.AI_INPT_CMN_CD = '3' LEFT OUTER JOIN CSPD112TI F ON F.AI_INPT_GRP_CD = '280' AND F.AI_INPT_CMN_CD = AA.AI_INPT_QLAS_PROS_CD LEFT OUTER JOIN CSPD112TI G ON G.AI_INPT_GRP_CD = '290' AND G.AI_INPT_CMN_CD = AA.AI_INPT_QLAS_ACVT_CD LEFT OUTER JOIN CSPD112TI H ON H.AI_INPT_GRP_CD = '170' AND H.AI_INPT_CMN_CD = AA.TOTALTEXT_AI_INPT_RST_CD LEFT OUTER JOIN CSPD112TI I ON I.AI_INPT_GRP_CD = '170' AND I.AI_INPT_CMN_CD = AA.ITM_INPT_AI_INPT_RST_CD LEFT OUTER JOIN CSPD112TI J ON J.AI_INPT_GRP_CD = '170' AND J.AI_INPT_CMN_CD = AA.SAFEWATCH_AI_INPT_RST_CD WHERE 1=1
AND AA.AI_INPT_CSNO = #{aiInptCsno}
